package app.rwun;

import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.text.*;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.nio.charset.StandardCharsets;import org.json.*;

/** Race-first, offline-capable onboarding. All mutations require a concrete preview. */
public final class RacePlanActivity extends Activity {
 private final UiKit.Palette p=new UiKit.Palette(true);
 private RunStore store;private LinearLayout body,results;private TextView message;private Bundle draft=new Bundle();private JSONArray catalogue=new JSONArray();private String stage="goal",catalogueNote="",fingerprint="";private LocalDate raceDate=LocalDate.now().plusWeeks(14),from=LocalDate.now(),to=LocalDate.now().plusYears(1);private Set<DayOfWeek> days=new HashSet<>(Set.of(DayOfWeek.TUESDAY,DayOfWeek.THURSDAY,DayOfWeek.SUNDAY));private DayOfWeek longDay=DayOfWeek.SUNDAY;private JSONObject selected;private RaceTraining.Draft preview;private List<ScheduleProposer.Change> changes=List.of();private RaceTraining.Review review;private boolean isRaceDraft=true,discoveryOpen;private String goalKind="race";private Button manualAdd;
 public void onCreate(Bundle state){super.onCreate(state);store=new RunStore(this);draft.putString("volume",store.config()==null?"12":String.valueOf(store.config().weeklyKm()));draft.putString("weeks","14");draft.putString("km","21.1");draft.putString("country","South Africa");draft.putString("surface","Road");draft.putString("longDay","SUNDAY");draft.putString("filterCountry","South Africa");draft.putString("distance","All distances");if("review".equals(getIntent().getStringExtra("mode")))stage="review";else if("search".equals(getIntent().getStringExtra("mode")))stage="search";
  if(state!=null)try{discoveryOpen=state.getBoolean("discoveryOpen");stage=state.getString("stage",stage);isRaceDraft=state.getBoolean("isRaceDraft",true);goalKind=state.getString("goalKind","race");draft=state.getBundle("draft");raceDate=LocalDate.parse(state.getString("race"));from=LocalDate.parse(state.getString("from"));to=LocalDate.parse(state.getString("to"));longDay=DayOfWeek.of(state.getInt("longDay",7));days.clear();for(int d:state.getIntArray("days"))days.add(DayOfWeek.of(d));if(state.containsKey("selected"))selected=new JSONObject(state.getString("selected"));}catch(Exception e){stage="search";}
  show();
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=620)return;discoveryOpen=false;if(result==RESULT_OK&&data!=null)try{select(new JSONObject(data.getStringExtra("race")));}catch(Exception e){error(e);}else if(result==RESULT_FIRST_USER){stage="manual";draft.putString("name","");draft.putString("city","");draft.remove("km");draft.putBoolean("manualDateSet",false);show();}else{stage="goal";show();}}
 protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putBoolean("discoveryOpen",discoveryOpen);out.putString("stage",stage);out.putBoolean("isRaceDraft",isRaceDraft);out.putString("goalKind",goalKind);out.putBundle("draft",draft);out.putString("race",raceDate.toString());out.putString("from",from.toString());out.putString("to",to.toString());out.putInt("longDay",longDay.getValue());out.putIntArray("days",days.stream().mapToInt(DayOfWeek::getValue).toArray());if(selected!=null)out.putString("selected",selected.toString());}
 private int dp(int n){return UiKit.dp(this,n);}private TextView text(String s,int size,boolean bold){TextView t=UiKit.label(this,s,size,size>=16?p.ink:p.muted,bold);body.addView(t);return t;}
 private LinearLayout panel(){return PlanningUi.card(this);}
 private LinearLayout card(){LinearLayout c=panel();body.addView(c);return c;}
 private void line(LinearLayout c,String s,int size){c.addView(UiKit.label(this,s,size,p.ink,size>=20));}
 private void action(String s,Runnable r){body.addView(UiKit.action(this,p,s,()->{try{r.run();}catch(Exception e){error(e);}}));}
 private void error(Exception e){new AlertDialog.Builder(this).setTitle("Check your plan").setMessage(UserErrors.message(e)).setPositiveButton("OK",null).show();}
 private void field(String label,String key,String fallback,boolean number){LinearLayout card=panel();card.setPadding(dp(18),dp(12),dp(18),dp(12));card.setBackground(PlanningUi.shape(this,PlanningUi.CARD,18,true));TextView caption=PlanningUi.label(this,label.toUpperCase(Locale.ROOT),12,false);caption.setTextColor(PlanningUi.INK);card.addView(caption);EditText e=new EditText(this);e.setTextColor(PlanningUi.INK);e.setHintTextColor(PlanningUi.MUTED);e.setTextSize(UiKit.textSizeSp(19));e.setSingleLine(true);e.setText(draft.getString(key,fallback));e.setHint(key.equals("name")?"What's the name of your race?":key.equals("city")?"Which city is the race in?":label);e.setContentDescription(label);e.setBackgroundColor(android.graphics.Color.TRANSPARENT);e.setPadding(0,dp(6),0,dp(4));e.setInputType(number?android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL:android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence value,int a,int b,int c){draft.putString(key,value.toString());updateManualButton();}public void afterTextChanged(Editable value){}});card.addView(e,new LinearLayout.LayoutParams(-1,dp(40)));body.addView(card);}
 private void selectField(String caption,String value,Runnable click){LinearLayout c=panel();c.setBackground(PlanningUi.shape(this,PlanningUi.CARD,18,true));if(!caption.isEmpty())c.addView(PlanningUi.label(this,caption.toUpperCase(Locale.ROOT),12,false));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView title=PlanningUi.label(this,value,19,false);title.setTextColor(PlanningUi.INK);row.addView(title,new LinearLayout.LayoutParams(0,-2,1));ImageView arrow=new ImageView(this);arrow.setImageDrawable(UiKit.icon(this,R.drawable.ic_chevron_right,PlanningUi.INK,20));arrow.setRotation(90);row.addView(arrow,new LinearLayout.LayoutParams(dp(24),dp(24)));c.addView(row);c.setMinimumHeight(dp(74));c.setClickable(true);c.setFocusable(true);c.setContentDescription(caption+", "+value);c.setOnClickListener(v->click.run());body.addView(c);}
 private void date(String label,LocalDate value,java.util.function.Consumer<LocalDate> changed){action(label+" · "+value,()->new DatePickerDialog(this,(v,y,m,d)->{changed.accept(LocalDate.of(y,m+1,d));show();},value.getYear(),value.getMonthValue()-1,value.getDayOfMonth()).show());}
 private void show(){try{manualAdd=null;LinearLayout root=PlanningUi.column(this);root.setBackgroundColor(PlanningUi.CANVAS);root.setFocusableInTouchMode(true);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});getWindow().setStatusBarColor(PlanningUi.CANVAS);getWindow().setNavigationBarColor(PlanningUi.CANVAS);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);int step=stage.equals("goal")?1:stage.equals("search")||stage.equals("manual")||stage.equals("distance")?2:stage.equals("fitness")?3:stage.equals("days")?4:5;root.addView(PlanningUi.header(this,step,this::back,this::finish));ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);scroll.setClipToPadding(false);body=PlanningUi.column(this);body.setPadding(dp(20),dp(10),dp(20),dp(30));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestFocus();results=null;message=null;
 switch(stage){case "goal":goal();break;case "distance":distanceGoal();break;case "manual":manual();break;case "fitness":fitness();break;case "days":availability();break;case "preview":preview();break;case "review":review();break;default:search();}
 }catch(Exception e){error(e);}}
 @Override public void onBackPressed(){back();}
 private void back(){switch(stage){case "search":case "distance":stage="goal";break;case "manual":stage="search";break;case "fitness":stage=isRaceDraft?"search":goalKind.equals("distance")?"distance":"goal";break;case "days":stage="fitness";break;case "preview":stage="days";break;default:finish();return;}show();}
 private void goal(){text("What is your goal?",30,true);text("Choose a goal that fits where you are now.",17,false);PlanningUi.gap(this,body,24);body.addView(PlanningUi.choice(this,R.drawable.ic_assignment,"Race","Choose an event and train toward race day.",()->{goalKind="race";isRaceDraft=true;stage="search";show();}));body.addView(PlanningUi.choice(this,R.drawable.ic_monitoring,"Run a specific distance","Build toward 5 km, 10 km, a half or a marathon.",()->goal("distance")));body.addView(PlanningUi.choice(this,R.drawable.ic_directions_run,"Start running","",()->goal("start")));body.addView(PlanningUi.choice(this,R.drawable.ic_refresh,"Get back into running","",()->goal("return")));body.addView(PlanningUi.choice(this,R.drawable.ic_monitoring,"5 km improvement","",()->goal("improve")));body.addView(PlanningUi.choice(this,R.drawable.ic_favorite,"General training","",()->goal("general")));body.addView(PlanningUi.choice(this,R.drawable.ic_info,"Help me choose","",()->new AlertDialog.Builder(this).setTitle("Choose your next step").setMessage("Have an event booked? Choose Race. New to running? Start running uses run/walk sessions. After a break, choose Get back into running. For consistency without an event, choose General training.").setPositiveButton("Got it",null).show()));}
 private void goal(String kind){goalKind=kind;isRaceDraft=false;selected=null;draft.putString("weeks",kind.equals("start")?"8":"12");draft.putString("km","5");stage=kind.equals("distance")?"distance":"fitness";show();}
 private void distanceGoal(){text("Choose your distance",30,true);text("One goal. A plan built around your week.",17,false);PlanningUi.gap(this,body,24);String[] labels={"5 km","10 km","Half marathon","Marathon"};double[] values={5,10,21.1,42.2};for(int i=0;i<labels.length;i++){final int n=i;body.addView(PlanningUi.choice(this,R.drawable.ic_directions_run,labels[i],"",()->{draft.putString("km",String.valueOf(values[n]));stage="fitness";show();}));}}
 private void search(){text("Find your race",28,true);text("Your saved catalogue opens immediately. Live feeds refresh in the background.",15,false);action("Browse races",()->{if(!discoveryOpen){discoveryOpen=true;startActivityForResult(new Intent(this,RaceDiscoveryActivity.class),620);}});action("Add a race manually",()->{stage="manual";show();});if(!discoveryOpen){discoveryOpen=true;startActivityForResult(new Intent(this,RaceDiscoveryActivity.class),620);}}
 private void dateFilter(){new AlertDialog.Builder(this).setTitle("Race dates").setItems(new String[]{"Next 3 months","Next 6 months","Next 12 months","Choose start date","Choose end date","Clear date filter"},(d,w)->{if(w<=2){from=LocalDate.now();to=from.plusMonths(new int[]{3,6,12}[w]);draft.putBoolean("dateFilter",true);show();}else if(w==5){from=LocalDate.now();to=from.plusYears(1);draft.putBoolean("dateFilter",false);show();}else{LocalDate value=w==3?from:to;new DatePickerDialog(this,(v,y,m,day)->{if(w==3)from=LocalDate.of(y,m+1,day);else to=LocalDate.of(y,m+1,day);draft.putBoolean("dateFilter",true);show();},value.getYear(),value.getMonthValue()-1,value.getDayOfMonth()).show();}}).show();}
 private void openUrl(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){error(e);}}
 private void select(JSONObject race){try{if(!race.getString("surface").equalsIgnoreCase("Road"))throw new IllegalArgumentException("This build supports road-running race plans. Trail-specific planning is not implemented.");double km=race.getDouble("km");if(km<5||km>42.2)throw new IllegalArgumentException("Race plans currently support 5 km through marathon; ultra training is not implemented.");selected=new JSONObject(race.toString());raceDate=LocalDate.parse(race.getString("date"));draft.putString("km",String.valueOf(km));draft.putString("name",race.getString("name"));draft.putString("city",race.optString("city"));draft.putString("country",race.optString("country"));long available=ChronoUnit.DAYS.between(LocalDate.now(),raceDate)/7;if(available<4)throw new IllegalArgumentException("This race is too soon for a four-week plan. Pick a later date; no catch-up programme will be compressed.");draft.putString("weeks",String.valueOf(Math.min(available,km>=42?20:km>=21?14:km>=10?10:8)));stage="fitness";show();}catch(Exception e){error(e);}}
 private void manual(){text("Add new race",30,true);text("Add the event details. We’ll use its distance and date to build your plan.",17,false);PlanningUi.gap(this,body,22);View divider=new View(this);divider.setBackgroundColor(PlanningUi.BORDER);body.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));PlanningUi.gap(this,body,24);field("Race name","name","",false);field("City","city","",false);selectField("Country",draft.getString("country","South Africa"),()->new AlertDialog.Builder(this).setTitle("Country").setItems(new String[]{"South Africa","Namibia","Botswana","Lesotho","Eswatini","Zimbabwe","Other"},(d,w)->{if(w<6){draft.putString("country",new String[]{"South Africa","Namibia","Botswana","Lesotho","Eswatini","Zimbabwe"}[w]);show();}else{EditText country=new EditText(this);country.setHint("Country");new AlertDialog.Builder(this).setTitle("Country").setView(country).setPositiveButton("Use country",(dialog,which)->{draft.putString("country",country.getText().toString().trim());show();}).setNegativeButton("Cancel",null).show();}}).show());selectField("Race date",draft.getBoolean("manualDateSet")?raceDate.format(java.time.format.DateTimeFormatter.ofPattern("dd MMM yyyy")):"Choose a date",()->new DatePickerDialog(this,(v,y,m,d)->{raceDate=LocalDate.of(y,m+1,d);draft.putBoolean("manualDateSet",true);show();},raceDate.getYear(),raceDate.getMonthValue()-1,raceDate.getDayOfMonth()).show());selectField("Distance",draft.containsKey("km")?PlanEngine.distance(Double.parseDouble(draft.getString("km"))):"Choose distance",()->new AlertDialog.Builder(this).setTitle("Race distance").setItems(new String[]{"5 km","10 km","Half marathon · 21.1 km","Marathon · 42.2 km","Other distance"},(d,w)->{if(w<4){draft.putString("km",String.valueOf(new double[]{5,10,21.1,42.2}[w]));show();}else{EditText custom=new EditText(this);custom.setInputType(8194);custom.setHint("Kilometres · 5–42.2");new AlertDialog.Builder(this).setTitle("Distance in km").setView(custom).setNegativeButton("Cancel",null).setPositiveButton("Use distance",(dialog,which)->{try{double distance=Double.parseDouble(custom.getText().toString());if(!Double.isFinite(distance)||distance<5||distance>42.2)throw new IllegalArgumentException("Enter 5–42.2 km. Ultra-specific plans are not available.");draft.putString("km",String.valueOf(distance));show();}catch(Exception e){error(e);}}).show();}}).show());selectField("Course profile",draft.getString("course","Not specified"),()->new AlertDialog.Builder(this).setTitle("Course profile").setItems(new String[]{"Not specified","Flat","Rolling","Hilly"},(d,w)->{draft.putString("course",new String[]{"Not specified","Flat","Rolling","Hilly"}[w]);show();}).show());text("Road-running plans · allow at least 4 weeks. Course profile is saved as context; hill-specific workouts are not generated.",12,false);manualAdd=UiKit.action(this,p,"Add race",()->{try{JSONObject race=new JSONObject().put("name",draft.getString("name").trim()).put("city",draft.getString("city").trim()).put("country",draft.getString("country").trim()).put("date",raceDate.toString()).put("km",Double.parseDouble(draft.getString("km"))).put("surface","Road").put("course",draft.getString("course","Not specified")).put("id","manual-"+UUID.randomUUID()).put("verified",LocalDate.now().toString());select(race);}catch(Exception e){error(e);}});body.addView(manualAdd);updateManualButton();}
 private void updateManualButton(){if(manualAdd==null)return;boolean valid=false;try{double km=Double.parseDouble(draft.getString("km",""));valid=!draft.getString("name","").trim().isEmpty()&&draft.getString("name").length()<=180&&!draft.getString("city","").trim().isEmpty()&&draft.getString("city").length()<=180&&!draft.getString("country","").trim().isEmpty()&&draft.getBoolean("manualDateSet")&&!raceDate.isBefore(LocalDate.now().plusWeeks(4))&&Double.isFinite(km)&&km>=5&&km<=42.2;}catch(Exception ignored){}manualAdd.setEnabled(valid);manualAdd.setAlpha(valid?1f:.4f);}
 private List<RaceTraining.Evidence> evidence(){return store.runs().stream().map(r->new RaceTraining.Evidence(LocalDate.parse(r.date()),r.km(),r.seconds(),r.rpe(),r.fatigue(),r.pain(),r.rpe()>0&&!r.source().startsWith("Health Connect")&&!r.source().equals("Strava"))).collect(java.util.stream.Collectors.toList());}
 private void history(RaceTraining.Review review){LinearLayout c=card();line(c,"YOUR RECENT RUNNING",12);line(c,review.runs28()+" runs · "+review.km28()+" km in 28 days",20);line(c,review.daysSinceLast()<0?"Last run: no recorded history":"Last run: "+review.daysSinceLast()+" days ago",15);line(c,"28-day weekly average: "+review.baseline()+" km",15);line(c,review.reason(),15);}
 private void fitness(){text("Start with your actual running",30,true);text(isRaceDraft?selected.optString("name")+" · "+raceDate:PlanEngine.distance(Double.parseDouble(draft.getString("km","5")))+" · "+(goalKind.equals("return")?"Return to running":goalKind.equals("start")?"Start running":"Your distance goal"),16,false);var review=RaceTraining.review(evidence(),LocalDate.now(),store.resting());history(review);field("Current weekly running distance (km)","volume","12",true);text("The reviewed baseline uses the lower of your entered volume and the recorded 28-day average when at least three runs are available. Missing history is not evidence that you did no exercise.",13,false);action("Continue",()->{double km=Double.parseDouble(draft.getString("volume"));if(!Double.isFinite(km)||km<4||km>120)throw new IllegalArgumentException("Enter 4–120 km of current weekly running.");stage="days";show();});}
 private void availability(){text("Make the plan fit your week",30,true);text("Choose the days you can consistently run.",17,false);PlanningUi.gap(this,body,20);field("Training weeks · 4–24","weeks","14",true);text("Training days · choose 2–5",18,true);PlanningUi.gap(this,body,12);DayOfWeek[] week=DayOfWeek.values();for(int group=0;group<2;group++){LinearLayout row=new LinearLayout(this);for(int i=group*4;i<Math.min(7,group*4+4);i++){DayOfWeek day=week[i];Button chip=PlanningUi.chip(this,day.getDisplayName(java.time.format.TextStyle.SHORT,Locale.getDefault()),days.contains(day),()->{if(days.contains(day))days.remove(day);else days.add(day);DayOfWeek chosen=DayOfWeek.valueOf(draft.getString("longDay","SUNDAY"));if(!days.contains(chosen)&&!days.isEmpty())draft.putString("longDay",days.stream().sorted().findFirst().get().name());show();});chip.setContentDescription(day.getDisplayName(java.time.format.TextStyle.FULL,Locale.getDefault()));chip.setSelected(days.contains(day));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(52),1);lp.setMargins(0,0,dp(6),0);row.addView(chip,lp);}body.addView(row);PlanningUi.gap(this,body,8);}PlanningUi.gap(this,body,16);DayOfWeek selectedDay=DayOfWeek.valueOf(draft.getString("longDay","SUNDAY"));selectField("Long-run day",selectedDay.getDisplayName(java.time.format.TextStyle.FULL,Locale.getDefault()),()->{String[] labels=days.stream().sorted().map(d->d.getDisplayName(java.time.format.TextStyle.FULL,Locale.getDefault())).toArray(String[]::new);DayOfWeek[] values=days.stream().sorted().toArray(DayOfWeek[]::new);new AlertDialog.Builder(this).setTitle("Long-run day").setItems(labels,(d,w)->{draft.putString("longDay",values[w].name());show();}).setNegativeButton("Cancel",null).show();});text(isRaceDraft?"Your plan works back from race day, with recovery and a shorter race week.":"Recovery days sit between your runs. Your long run stays on your chosen day.",14,false);action("Preview my plan",()->{longDay=DayOfWeek.valueOf(draft.getString("longDay",longDay.toString()));buildPreview();stage="preview";show();});}
 private RaceTraining.Draft buildPreview(){if(isRaceDraft&&selected==null)throw new IllegalStateException("Choose a race first");int weeks=Integer.parseInt(draft.getString("weeks"));longDay=DayOfWeek.valueOf(draft.getString("longDay",longDay.toString()));preview=isRaceDraft?RaceTraining.draft(LocalDate.now(),raceDate,selected.optDouble("km"),weeks,days,longDay,Double.parseDouble(draft.getString("volume")),store.profile(),evidence(),store.resting()):RaceTraining.goalDraft(LocalDate.now(),Double.parseDouble(draft.getString("km","5")),weeks,days,longDay,Double.parseDouble(draft.getString("volume")),store.profile(),evidence(),store.resting(),goalKind);fingerprint=store.proposalFingerprint();return preview;}
 private void preview(){var plan=buildPreview();text("Your plan, ready to review",29,true);LinearLayout c=card();line(c,isRaceDraft?selected.optString("name"):PlanEngine.distance(plan.config().goalKm())+" journey",24);if(isRaceDraft)line(c,raceDate+" · "+PlanEngine.distance(plan.config().goalKm())+" · "+selected.optString("city"),16);line(c,plan.config().weeks()+" weeks · "+days.size()+" runs each week",16);line(c,"Starts "+plan.config().start()+" · "+plan.config().weeklyKm()+" km/week baseline",14);text("YOUR FIRST WEEK",12,true);for(var session:plan.sessions())if(session.date().isBefore(plan.config().start().plusDays(7))){LinearLayout workout=card();line(workout,session.date().format(java.time.format.DateTimeFormatter.ofPattern("EEE, d MMM")),13);line(workout,session.title()+" · "+PlanEngine.distance(session.km()),18);}if(plan.review().hold())text("Training remains paused. Review your hold before recording planned sessions.",16,true);action("How this plan was built",()->new AlertDialog.Builder(this).setTitle("Your training baseline").setMessage(plan.review().reason()+"\n\n"+plan.warning()+"\n\nOriginal OpenRun rules; not reviewed by a qualified coach.").setPositiveButton("Done",null).show());if(isRaceDraft){action("Review race week",()->{StringBuilder week=new StringBuilder();for(var session:plan.sessions())if(!session.date().isBefore(raceDate.minusDays(7)))week.append(session.date()).append(" · ").append(session.title()).append(" · ").append(PlanEngine.distance(session.km())).append("\n");new AlertDialog.Builder(this).setTitle("Race week").setMessage(week+"\nRace day: "+raceDate).setPositiveButton("Done",null).show();});if(selected.has("source"))action("Check event source",()->openUrl(selected.optString("source")));}action(plan.review().hold()?"Create paused plan":"Create my plan",()->new AlertDialog.Builder(this).setTitle("Use this plan?").setMessage("This replaces your current schedule. Saved activities and any training hold remain. The exact preview is saved."+(isRaceDraft?" No race entry is purchased.":"")).setNegativeButton("Keep editing",null).setPositiveButton("Create",(d,w)->save()).show());action("Create plan and personalise with AI",()->new AlertDialog.Builder(this).setTitle("Save this plan and open AI Coach?").setMessage("This saves the reviewed schedule, replacing your current plan while keeping saved activities and recovery holds. AI Coach will then use your own API key to propose personalisation.").setNegativeButton("Keep editing",null).setPositiveButton("Continue",(dialog,which)->save(true)).show());}
 private void save(){save(false);}
 private void save(boolean openAiCoach){try{if(preview.review().hold()&&!store.resting())throw new IllegalStateException("Recent reported pain needs a training-hold review before creating a runnable plan.");if(!fingerprint.equals(store.proposalFingerprint()))throw new IllegalStateException("Your running history or plan changed. Refresh the preview first.");JSONObject options=new JSONObject();JSONArray weekday=new JSONArray();for(DayOfWeek d:days)weekday.put(d.getValue());options.put("mode",preview.preferences().mode()).put("weekdays",weekday).put("longDay",longDay.getValue());PaceProfile profile=preview.preferences().mode().equals("Return to running")?new PaceProfile(store.profile().distanceKm(),store.profile().seconds(),false):store.profile();if(isRaceDraft)store.createRacePlan(fingerprint,preview.config(),profile,selected,options,preview.sessions());else store.createGoalPlan(fingerprint,preview.config(),profile,options,preview.sessions());Reminders.schedule(this);WorkoutWidget.updateAll(this);setResult(RESULT_OK);if(openAiCoach)startActivity(new Intent(this,AiCoachActivity.class));finish();}catch(Exception e){error(e);}}
 private void review(){text("Adapt from your recent running",29,true);review=RaceTraining.review(evidence(),LocalDate.now(),store.resting());history(review);if(store.config()==null){text("Create a plan to review upcoming workouts.",16,false);return;}List<PlanEngine.Session> pending=store.plannedSessions().stream().filter(s->!store.completed(store.planId()+":"+s.id())&&!store.skipped(store.planId()+":"+s.id())).collect(java.util.stream.Collectors.toList());changes=store.v103().optString("raceReview").equals(reviewTicket())?List.of():RaceTraining.changes(pending,review,LocalDate.now());fingerprint=store.proposalFingerprint();if(changes.isEmpty())text("No changes proposed. The current plan and training hold remain as they are.",16,false);else{text(store.previewProposal(fingerprint,changes,reviewTicket()),16,true);action("Apply reviewed changes",()->{store.applyReviewedProposal(fingerprint,changes,reviewTicket());Reminders.schedule(this);WorkoutWidget.updateAll(this);Toast.makeText(this,"Reviewed changes saved",Toast.LENGTH_LONG).show();finish();});}action("AI Coach · use my API key",()->startActivity(new Intent(this,AiCoachActivity.class)));text("These software rules propose reductions, never automatic mileage increases or a training-hold clearance. Imported effort is not inferred.",13,false);}
 private String reviewTicket(){try{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest((store.planId()+store.runs().toString()).getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:hash)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
}
